# Generates studio-style SVG product images for every product in data.js
import re, json, sys, os, colorsys
src = open(sys.argv[1]).read(); out = sys.argv[2]; os.makedirs(out, exist_ok=True)
rows = re.findall(r'\["(p\d+)", "((?:[^"\\]|\\.)*)", "([^"]+)", "(\w+)", "(\w+)", "([\w-]+)"(.*?)\],\n', src)
def shade(h, f):
    h=h.lstrip('#'); h=''.join(c*2 for c in h) if len(h)==3 else h
    r,g,b=[int(h[i:i+2],16)/255 for i in (0,2,4)]; H,L,S=colorsys.rgb_to_hls(r,g,b)
    L=max(0,min(1,L*f if f<1 else L+(1-L)*(f-1))); r,g,b=colorsys.hls_to_rgb(H,L,S)
    return '#%02x%02x%02x'%(int(r*255),int(g*255),int(b*255))
BG=[("#fff4ec","#ffe2cf"),("#eef3ff","#d9e4ff"),("#eefaf3","#d3f0e0"),("#fdf0f4","#f8d9e4"),("#f3efff","#e1d8ff"),("#ecf7fc","#d2ecf7"),("#fff8e8","#ffebc2"),("#f4f5f7","#e3e6ea")]
DEF={"p-phone":"#2b2d33","p-headphones":"#1f1f22","p-laptop":"#9aa3ad","p-watch":"#2b2d33","p-tv":"#111","p-camera":"#222","p-shirt":"#1f2a44","p-shoe":"#e8e8e8","p-bottle":"#f5f5f5","p-perfume":"#c88a3a","p-pan":"#2b2b2b","p-sofa":"#9aa0a6","p-milk":"#ffffff","p-toy":"#e53935","p-baby":"#4a6fa5","p-book":"#1f6f5c","p-ball":"#ffffff","p-car":"#2b2d33"}
def lab(t,x,y,s=14,c="#fff",w=700): return f'<text x="{x}" y="{y}" font-family="Inter,Arial,sans-serif" font-size="{s}" font-weight="{w}" fill="{c}" text-anchor="middle">{t}</text>'
def draw(g,c,brand,title):
    d,l=shade(c,.6),shade(c,1.35); B=brand.replace("&","&amp;").replace("'","&#39;")[:14]
    if g=="p-phone": return f'''<rect x="150" y="70" width="200" height="380" rx="34" fill="url(#body)"/><rect x="160" y="80" width="180" height="360" rx="26" fill="#0b0d12"/><rect x="166" y="86" width="168" height="348" rx="22" fill="url(#scr)"/><circle cx="250" cy="102" r="6" fill="#000"/><path d="M166 300 Q250 220 334 270 V434 H166Z" fill="#fff" opacity=".12"/><rect x="200" y="400" width="100" height="5" rx="2.5" fill="#fff" opacity=".7"/><rect x="346" y="150" width="6" height="50" rx="3" fill="{d}"/>{lab(B,250,260,18)}'''
    if g=="p-headphones": return f'''<path d="M140 290 V240 A110 110 0 0 1 360 240 V290" fill="none" stroke="{d}" stroke-width="22" stroke-linecap="round"/><path d="M150 240 A100 100 0 0 1 350 240" fill="none" stroke="{l}" stroke-width="6" opacity=".5"/><rect x="105" y="270" width="80" height="130" rx="36" fill="url(#body)"/><rect x="315" y="270" width="80" height="130" rx="36" fill="url(#body)"/><rect x="170" y="285" width="22" height="100" rx="10" fill="{d}"/><rect x="308" y="285" width="22" height="100" rx="10" fill="{d}"/><ellipse cx="128" cy="320" rx="10" ry="30" fill="#fff" opacity=".18"/>{lab(B,355,345,11)}'''
    if g=="p-laptop": return f'''<rect x="95" y="110" width="310" height="210" rx="14" fill="url(#body)"/><rect x="108" y="122" width="284" height="186" rx="6" fill="url(#scr)"/><path d="M108 250 Q250 170 392 220 V308 H108Z" fill="#fff" opacity=".12"/><path d="M60 330 H440 L420 360 H80Z" fill="{l}"/><rect x="60" y="326" width="380" height="8" rx="4" fill="{d}"/><rect x="215" y="330" width="70" height="5" rx="2" fill="{d}" opacity=".5"/>{lab(B,250,222,16)}'''
    if g=="p-watch": return f'''<rect x="200" y="60" width="100" height="120" rx="20" fill="{d}"/><rect x="200" y="330" width="100" height="120" rx="20" fill="{d}"/><rect x="165" y="150" width="170" height="210" rx="46" fill="url(#body)"/><rect x="180" y="165" width="140" height="180" rx="36" fill="#0b0d12"/><circle cx="250" cy="255" r="58" fill="none" stroke="#ff6a00" stroke-width="10" stroke-dasharray="250 400" transform="rotate(-90 250 255)"/><circle cx="250" cy="255" r="42" fill="none" stroke="#3ddc97" stroke-width="8" stroke-dasharray="160 400" transform="rotate(-90 250 255)"/>{lab("10:09",250,262,22)}<rect x="336" y="220" width="10" height="34" rx="5" fill="{d}"/>'''
    if g=="p-tv": return f'''<rect x="55" y="100" width="390" height="240" rx="10" fill="#15171c"/><rect x="63" y="108" width="374" height="224" rx="4" fill="url(#scr)"/><path d="M63 260 Q250 150 437 230 V332 H63Z" fill="#fff" opacity=".12"/><path d="M200 340 L180 395 H320 L300 340Z" fill="#2a2d33"/><rect x="160" y="392" width="180" height="10" rx="5" fill="#1b1d22"/>{lab(B,250,228,22)}'''
    if g=="p-camera": return f'''<rect x="90" y="160" width="320" height="210" rx="28" fill="url(#body)"/><rect x="130" y="130" width="90" height="40" rx="10" fill="{d}"/><circle cx="265" cy="268" r="88" fill="#1a1a1a"/><circle cx="265" cy="268" r="70" fill="#2c2c2c"/><circle cx="265" cy="268" r="48" fill="url(#lens)"/><circle cx="248" cy="250" r="12" fill="#fff" opacity=".35"/><rect x="350" y="185" width="36" height="20" rx="5" fill="#ff6a00"/>{lab(B,150,215,14)}'''
    if g=="p-shirt": return f'''<path d="M180 85 L110 120 L70 210 L130 235 L150 200 V430 H350 V200 L370 235 L430 210 L390 120 L320 85 Q250 140 180 85Z" fill="url(#body)"/><path d="M180 85 Q250 140 320 85" fill="none" stroke="{d}" stroke-width="10"/><path d="M215 100 L250 160 L285 100" fill="none" stroke="{d}" stroke-width="5" opacity=".6"/><path d="M150 200 V430" stroke="{d}" stroke-width="3" opacity=".3"/><circle cx="295" cy="190" r="12" fill="{l}" opacity=".9"/>'''
    if g=="p-shoe": return f'''<path d="M60 330 Q60 250 110 230 L200 210 Q240 260 300 270 L400 290 Q450 300 450 345 V360 H60Z" fill="url(#body)"/><path d="M60 345 H450 V375 Q450 385 440 385 H70 Q60 385 60 375Z" fill="#fafafa" stroke="#ddd"/><path d="M60 360 H450" stroke="#ff6a00" stroke-width="5"/><path d="M210 230 L245 265 M230 222 L262 262 M250 218 L282 260" stroke="#fff" stroke-width="6" stroke-linecap="round"/><path d="M120 300 Q220 260 360 320" fill="none" stroke="{d}" stroke-width="10" stroke-linecap="round" opacity=".7"/>'''
    if g=="p-bottle": return f'''<rect x="215" y="70" width="70" height="60" rx="8" fill="#222"/><rect x="225" y="125" width="50" height="25" fill="#ddd"/><rect x="170" y="150" width="160" height="290" rx="40" fill="url(#body)" stroke="#e0e0e0"/><rect x="185" y="230" width="130" height="130" rx="10" fill="#ff6a00"/>{lab(B,250,280,15)}{lab("PREMIUM",250,305,11,"#fff",600)}<rect x="190" y="165" width="20" height="250" rx="10" fill="#fff" opacity=".5"/>'''
    if g=="p-perfume": return f'''<rect x="225" y="80" width="50" height="55" rx="6" fill="#1c1c1c"/><rect x="235" y="130" width="30" height="30" fill="#c9a55c"/><rect x="140" y="160" width="220" height="270" rx="30" fill="url(#body)" opacity=".92"/><rect x="160" y="180" width="180" height="230" rx="22" fill="#fff" opacity=".12"/><rect x="185" y="270" width="130" height="50" rx="4" fill="#1c1c1c" opacity=".85"/>{lab(B.upper(),250,301,14,"#e9cf8f")}<rect x="155" y="175" width="18" height="230" rx="9" fill="#fff" opacity=".35"/>'''
    if g=="p-pan": return f'''<ellipse cx="220" cy="290" rx="150" ry="70" fill="{d}"/><ellipse cx="220" cy="275" rx="150" ry="70" fill="url(#body)"/><ellipse cx="220" cy="270" rx="125" ry="55" fill="#1d1d1d"/><ellipse cx="190" cy="255" rx="50" ry="16" fill="#fff" opacity=".1"/><rect x="355" y="230" width="120" height="26" rx="13" fill="#333" transform="rotate(-18 355 240)"/>{lab(B,220,370,14,"#333")}'''
    if g=="p-sofa": return f'''<rect x="90" y="170" width="320" height="130" rx="26" fill="url(#body)"/><rect x="60" y="240" width="380" height="110" rx="24" fill="{c}"/><rect x="40" y="220" width="70" height="140" rx="30" fill="{d}"/><rect x="390" y="220" width="70" height="140" rx="30" fill="{d}"/><rect x="120" y="250" width="125" height="50" rx="14" fill="{l}" opacity=".6"/><rect x="255" y="250" width="125" height="50" rx="14" fill="{l}" opacity=".6"/><rect x="85" y="355" width="12" height="40" rx="4" fill="#5a4030"/><rect x="403" y="355" width="12" height="40" rx="4" fill="#5a4030"/>'''
    if g=="p-milk": return f'''<path d="M180 120 L210 80 H290 L320 120 V430 H180Z" fill="#fafafa" stroke="#e0e0e0" stroke-width="2"/><path d="M180 120 H320 V170 H180Z" fill="#ff6a00"/><rect x="230" y="62" width="40" height="22" rx="4" fill="#1e88e5"/><rect x="180" y="250" width="140" height="110" fill="#e8f1fb"/>{lab(B,250,300,16,"#1e4e8c")}{lab(title.split()[0][:10],250,325,11,"#1e4e8c",600)}<rect x="188" y="130" width="12" height="290" fill="#fff" opacity=".7"/>'''
    if g=="p-toy": return f'''<rect x="130" y="260" width="240" height="150" rx="10" fill="#e53935"/><rect x="160" y="190" width="180" height="80" rx="8" fill="#fbc02d"/><g fill="#e53935">{''.join(f'<circle cx="{150+i*40}" cy="258" r="12"/>' for i in range(6))}</g><g fill="#fbc02d">{''.join(f'<circle cx="{180+i*40}" cy="188" r="12"/>' for i in range(4))}</g><rect x="210" y="320" width="80" height="90" fill="#8d1d1d"/><rect x="160" y="300" width="40" height="40" fill="#bbdefb"/><rect x="300" y="300" width="40" height="40" fill="#bbdefb"/>{lab(B,250,240,18,"#7a1515")}'''
    if g=="p-baby": return f'''<circle cx="170" cy="400" r="34" fill="#333"/><circle cx="350" cy="400" r="34" fill="#333"/><circle cx="170" cy="400" r="14" fill="#999"/><circle cx="350" cy="400" r="14" fill="#999"/><path d="M120 250 H390 Q400 360 300 370 H200 Q110 360 120 250Z" fill="url(#body)"/><path d="M120 250 Q130 120 260 110 L270 250Z" fill="{d}"/><path d="M390 250 L440 150" stroke="#444" stroke-width="10" stroke-linecap="round"/><path d="M180 370 L170 400 M330 370 L350 400" stroke="#444" stroke-width="8"/>'''
    if g=="p-book": return f'''<rect x="150" y="80" width="210" height="330" rx="8" fill="url(#body)"/><rect x="150" y="80" width="22" height="330" fill="{d}"/><rect x="360" y="90" width="12" height="310" fill="#f1f1f1"/><rect x="195" y="140" width="140" height="4" fill="#fff" opacity=".7"/>{lab(B,265,200,18)}{lab(" ".join(title.split()[:2])[:16],265,230,13,"#fff",500)}<circle cx="265" cy="310" r="40" fill="#ff6a00" opacity=".9"/>'''
    if g=="p-ball": return f'''<circle cx="250" cy="260" r="160" fill="url(#body)" stroke="#ddd"/><polygon points="250,190 300,225 282,285 218,285 200,225" fill="#222"/><path d="M250 190 V100 M300 225 L380 195 M282 285 L330 360 M218 285 L170 360 M200 225 L120 195" stroke="#222" stroke-width="5"/><circle cx="195" cy="190" r="40" fill="#fff" opacity=".35"/>'''
    if g=="p-car": return f'''<rect x="160" y="130" width="180" height="250" rx="24" fill="url(#body)"/><rect x="172" y="145" width="156" height="220" rx="16" fill="url(#scr)"/><path d="M200 380 L250 420 L300 380" fill="{d}"/><rect x="215" y="415" width="70" height="30" rx="10" fill="#333"/><circle cx="250" cy="255" r="30" fill="#ff6a00" opacity=".9"/>'''
    return ''
for i,(pid,title,brand,cat,group,glyph,rest) in enumerate(rows):
    m=re.search(r'colors: \[\["[^"]+", "(#[0-9a-fA-F]{3,6})"',rest); c=m.group(1) if m else DEF.get(glyph,"#555")
    b1,b2=BG[i%8]
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 500" width="500" height="500"><defs><radialGradient id="bg" cx="50%" cy="40%" r="70%"><stop offset="0" stop-color="#fff"/><stop offset=".55" stop-color="{b1}"/><stop offset="1" stop-color="{b2}"/></radialGradient><linearGradient id="body" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{shade(c,1.25)}"/><stop offset=".55" stop-color="{c}"/><stop offset="1" stop-color="{shade(c,.7)}"/></linearGradient><linearGradient id="scr" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ff8a3d"/><stop offset=".5" stop-color="#d64000"/><stop offset="1" stop-color="#3b1a6b"/></linearGradient><radialGradient id="lens"><stop offset="0" stop-color="#5b7cff"/><stop offset=".6" stop-color="#1b1f4a"/><stop offset="1" stop-color="#05060d"/></radialGradient><filter id="sh" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="0" dy="14" stdDeviation="14" flood-color="#000" flood-opacity=".18"/></filter></defs><rect width="500" height="500" fill="url(#bg)"/><ellipse cx="250" cy="460" rx="170" ry="16" fill="#000" opacity=".08"/><g filter="url(#sh)">{draw(glyph,c,brand,title)}</g></svg>'''
    open(f"{out}/{pid}.svg","w").write(svg)
print(len(rows))
